def check_girth(adj):
    """Return the girth of the graph, or a large number if no cycle"""
    n = len(adj)
    min_cycle = n + 1
    for s in range(n):
        parent = {s: -1}
        dist = {s: 0}
        stack = [s]
        while stack:
            v = stack.pop()
            for u in adj[v]:
                if u not in dist:
                    dist[u] = dist[v] + 1
                    parent[u] = v
                    stack.append(u)
                elif u != parent[v]:
                    cycle_len = dist[v] + dist[u] + 1
                    if cycle_len < min_cycle:
                        min_cycle = cycle_len
    return min_cycle

def try_construct(max_attempts=5000):
    for attempt in range(max_attempts):
        adj = [set() for _ in range(n)]
        degrees = [0] * n

        # Target degrees: all between 3 and 7
        # Let's try 3-regular first (since (3,7)-cage exists with 24 vertices)
        target = [3] * n

        total_edges_needed = sum(target) // 2

        # Try adding edges in random order
        possible = [(i, j) for i in range(n) for j in range(i+1, n)]
        random.shuffle(possible)

        for (i, j) in possible:
            if degrees[i] >= target[i] or degrees[j] >= target[j]:
                continue

            # Temporarily add edge
            adj[i].add(j)
            adj[j].add(i)

            if check_girth(adj) >= 7:
                degrees[i] += 1
                degrees[j] += 1
            else:
                adj[i].remove(j)
                adj[j].remove(i)

        if all(d >= 3 for d in degrees):
            return adj, degrees

